 92→import { loadToolDefinition, buildToolSchema, CustomToolDefinition } from './loader.js';
 93→import { exec } from 'child_process';
 94→import util from 'util';
 95→const execPromise = util.promisify(exec);
 96→import chokidar from 'chokidar';
 97→import fs from 'fs';
 98→import { TOOLS_DIR } from '../config/paths.js';
 99→
100→// ============================================================================
101→// Internal Types
102→// ============================================================================
103→
104→/** Internal tool registration record used by the registry. */
105→export interface OrchestratorTool {
106→  /** Tool name */
107→  name: string; // broadened from ToolName for custom tools
108→  /** Tool description */
109→  description: string;
110→  /** Handler function */
111→  handler: (input: unknown, context?: ToolContext) => Promise<ToolResult>;
112→  /** Zod schema for validation */
113→  schema: z.ZodSchema;
114→  /** Safety level */
115→  danger?: DangerLevel;
116→  /** Is this a custom tool? */
117→  isCustom?: boolean;
118→  /** When true, tool can only run in local execution mode */
119→  localOnly?: boolean;
120→  /** Permission level required to execute this tool */
121→  permission?: ToolPermission;
122→}
123→
124→/** Async tool handler signature used by built-in and custom tools. */
125→export type ToolHandler = (input: unknown, context?: ToolContext) => Promise<ToolResult>;
126→
127→// ============================================================================
128→// Tool Registry Class
129→// ============================================================================
130→
131→export class ToolRegistry {
132→  private static instance: ToolRegistry | undefined;
133→  private tools: Map<string, OrchestratorTool> = new Map();
134→  private customToolFiles: Map<string, string> = new Map(); // filePath → toolName
135→  private customToolsDir: string;
136→  private watchers: ReturnType<typeof chokidar.watch>[] = [];
137→
138→  private constructor() {
139→    this.customToolsDir = TOOLS_DIR;
140→    this.registerBuiltins();
141→    this.initCustomTools();
142→  }
143→
144→  private initCustomTools() {
145→    // Ensure dir exists (or try to)
146→    if (!fs.existsSync(this.customToolsDir)) {
147→      // Ideally we create it, but constructor sync content... 
148→      // Async init pattern better, but singleton is sync accessed usually.
149→      // We'll set up watcher and let it fire on existing files if configured right.
150→    }
151→
152→    this.setupWatcher();
153→  }
154→
155→  private setupWatcher() {
156→    try {
157→      const watcher = chokidar.watch(this.customToolsDir, {
158→        ignored: /(^|[/\\])\../,
159→        persistent: true,
160→        depth: 0
161→      });
162→
163→      watcher.on('add', (f) => this.loadCustomTool(f));
164→      watcher.on('change', (f) => this.loadCustomTool(f));
165→      watcher.on('unlink', (f) => this.unloadCustomTool(f));
166→
167→      this.watchers.push(watcher);
168→    } catch (err) {
169→      logger.error('Failed to setup tool watcher', err);
170→    }
171→  }
172→
173→  private async loadCustomTool(filePath: string) {
174→    if (!filePath.endsWith('.json')) return;
175→    const previousName = this.customToolFiles.get(filePath);
176→
177→    try {
178→      const def = await loadToolDefinition(filePath);
179→      if (!def) {
180→        if (previousName) {
181→          this.tools.delete(previousName);
182→          this.customToolFiles.delete(filePath);
183→          logger.info(`Custom tool unloaded due to invalid definition: ${previousName}`);
184→        }
185→        return;
186→      }
187→
188→      if (previousName && previousName !== def.name) {
189→        this.tools.delete(previousName);
190→        logger.info(`Custom tool renamed: ${previousName} -> ${def.name}`);
191→      }
192→
193→      const schema = buildToolSchema(def);
194→      const handler = this.createShellHandler(def);
195→
196→      const tool: OrchestratorTool = {
197→        name: def.name,
198→        description: def.description,
199→        danger: def.danger,
200→        schema,
201→        handler,
202→        isCustom: true
203→      };
204→
205→      this.register(tool);
206→      this.customToolFiles.set(filePath, def.name);
207→      logger.info(`Custom tool loaded: ${tool.name}`);
208→    } catch (error) {
209→      logger.error(`Failed to reload custom tool: ${filePath}`, { error });
210→      if (previousName) {
211→        this.tools.delete(previousName);
212→        this.customToolFiles.delete(filePath);
213→        logger.info(`Custom tool unloaded after reload failure: ${previousName}`);
214→      }
215→    }
216→  }
217→
218→  private unloadCustomTool(filePath: string) {
219→    const toolName = this.customToolFiles.get(filePath);
220→    if (toolName) {
221→      this.tools.delete(toolName);
222→      this.customToolFiles.delete(filePath);
223→      logger.info(`Custom tool unloaded: ${toolName}`);
224→    }
225→  }
226→
227→  private createShellHandler(def: CustomToolDefinition): ToolHandler {
228→    return async (input: unknown) => {
229→      const params = input as Record<string, unknown>;
230→      let command = def.command;
231→
232→      // Template replacement: {{param}} with shell-safe escaping
233→      Object.keys(params).forEach(key => {
234→        const val = String(params[key]);
235→        // Escape single quotes and wrap in single quotes for shell safety
236→        const escaped = "'" + val.replace(/'/g, "'\\''") + "'";
237→        command = command.replace(new RegExp(`{{${key}}}`, 'g'), escaped);
238→      });
239→
240→      const MAX_SHELL_OUTPUT = 100_000;
241→      const start = Date.now();
242→      try {
243→        const cwd = def.cwd || process.cwd();
244→        const { stdout, stderr } = await execPromise(command, { cwd });
245→        const truncatedOutput = (stdout || stderr || 'Command executed successfully').slice(0, MAX_SHELL_OUTPUT);
246→
247→        return {
248→          success: true,
249→          output: truncatedOutput,
250→          duration: Date.now() - start
251→        };
252→      } catch (error) {
253→        const err = error as { stdout?: string; message?: string; stderr?: string };
254→        return {
255→          success: false,
256→          output: err.stdout || '',
257→          error: err.message || err.stderr || 'Unknown execution error',
258→          duration: Date.now() - start
259→        };
260→      }
261→    };
262→  }
263→
264→  public static getInstance(): ToolRegistry {
265→    if (!ToolRegistry.instance) {
266→      ToolRegistry.instance = new ToolRegistry();
267→    }
268→    return ToolRegistry.instance;
269→  }
270→
271→  /** Closes custom-tool watchers and releases watcher resources. */
272→  public async shutdown(): Promise<void> {
273→    for (const watcher of this.watchers) {
274→      await watcher.close();
275→    }
276→    this.watchers = [];
277→  }
278→
279→  /** Registers one tool definition (insert/replace by tool name). */
280→  public register(tool: OrchestratorTool): void {
281→    this.tools.set(tool.name, tool);
282→    logger.debug(`Registered tool: ${tool.name}`);
283→  }
284→
285→  /** Registers a dictionary of tools. */
286→  public registerAll(tools: Record<string, OrchestratorTool>): void {
287→    for (const tool of Object.values(tools)) {
288→      this.register(tool);
289→    }
290→  }
291→
292→  /** Returns one tool by name, if registered. */
293→  public get(name: string): OrchestratorTool | undefined {
294→    return this.tools.get(name);
295→  }
296→
297→  /** Returns all currently registered tools. */
298→  public list(): OrchestratorTool[] {
299→    return Array.from(this.tools.values());
300→  }
301→
302→  /** Returns registered tools in OpenAI function-calling format. */
303→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
304→  public toOpenAIFormat(toolNames?: string[]): any[] {
305→    const selected = toolNames && toolNames.length > 0
306→      ? toolNames
307→        .map((name) => this.tools.get(name))
308→        .filter((tool): tool is OrchestratorTool => !!tool)
309→      : Array.from(this.tools.values());
310→    const result = selected.map(tool => _mapToOpenAIFunction(tool));
311→
312→    // Log schemas once on first call for debugging
313→    if (!this._schemaLogged) {
314→      this._schemaLogged = true;
315→      for (const tool of result) {
316→        // eslint-disable-next-line @typescript-eslint/no-explicit-any
317→        const fn = (tool as any).function;
318→        logger.debug('Tool schema', {
319→          name: fn?.name,
320→          parameters: JSON.stringify(fn?.parameters),
321→        });
322→      }
323→    }
324→
325→    return result;
326→  }
327→
328→  private _schemaLogged = false;
329→
330→  /** Validates input and executes a registered tool handler by name. */
331→  public async execute(name: string, args: unknown, context?: ToolContext): Promise<ToolResult> {
332→    const tool = this.tools.get(name);
333→    logger.info(`ToolRegistry.execute called: ${name}`, { found: !!tool, hasHandler: !!tool?.handler });
334→    if (!tool) {
335→      return {
336→        success: false,
337→        output: `Tool '${name}' not found`,
338→        duration: 0
339→      };
340→    }
341→
342→    const startTime = Date.now();
343→    try {
344→      const autonomyLevel = context?.autonomyLevel ?? 'cautious';
345→
346→      // Enforce autonomy policy before schema/handler execution.
347→      // This is a hard safety layer independent of prompt behavior.
348→      if (tool.danger === DangerLevel.DANGEROUS) {
349→        if (autonomyLevel === 'supervised') {
350→          return {
351→            success: false,
352→            output: `Safety policy blocked dangerous tool '${name}' in supervised mode. Request explicit operator intervention or switch autonomy level.`,
353→            duration: Date.now() - startTime,
354→          };
355→        }
356→        if (autonomyLevel === 'cautious' && !hasExplicitConfirmation(args)) {
357→          return {
358→            success: false,
359→            output: `Tool '${name}' requires manual confirmation in Cautious Mode. You MUST use the 'ask_user' tool to request permission from the operator explaining exactly what you intend to do. If they approve, retry this action with 'confirm: true'.`,
360→            duration: Date.now() - startTime,
361→          };
362→        }
363→      }
364→
365→      // Validate args with Zod safeParse — lets the LLM self-correct bad arguments
366→      const validation = tool.schema.safeParse(args);
367→      if (!validation.success) {
368→        const issues = validation.error.issues
369→          .map((i) => `${i.path.join('.')}: ${i.message}`)
370→          .join('; ');
371→        logger.warn(`Tool validation failed: ${name}`, { issues });
372→        return {
373→          success: false,
374→          output: `Validation error for tool '${name}': ${issues}. Please fix the arguments and try again.`,
375→          duration: Date.now() - startTime
376→        };
377→      }
378→
379→      const result = await tool.handler(validation.data, context);
380→      // Ensure duration is present if tool doesn't provide it
381→      if (result.duration === undefined) {
382→        result.duration = Date.now() - startTime;
383→      }
384→      return result;
385→    } catch (error) {
386→      logger.error(`Tool execution failed: ${name}`, { error });
387→      return {
388→        success: false,
389→        output: `Error executing tool '${name}': ${error instanceof Error ? error.message : String(error)}`,
390→        duration: Date.now() - startTime
391→      };
392→    }
393→  }
394→
395→  private registerBuiltins(): void {
396→    const P = ToolPermission;
397→    const builtins: Record<string, { h: ToolHandler; s: z.ZodSchema; d: DangerLevel; lo?: boolean; p?: ToolPermission }> = {
398→      // WORKSPACE — filesystem tools are local-only
399→      workspace_list:    { h: handleWorkspaceList,    s: ToolInputSchemas.workspace_list,    d: DangerLevel.SAFE,      lo: true, p: P.READ },
400→      workspace_select:  { h: handleWorkspaceSelect,  s: ToolInputSchemas.workspace_select,  d: DangerLevel.SAFE,      lo: true, p: P.READ },
401→      workspace_status:  { h: handleWorkspaceStatus,  s: ToolInputSchemas.workspace_status,  d: DangerLevel.SAFE,      lo: true, p: P.READ },
402→      workspace_create:  { h: handleWorkspaceCreate,  s: ToolInputSchemas.workspace_create,  d: DangerLevel.MODERATE,  lo: true, p: P.WRITE },
403→      workspace_delete:  { h: handleWorkspaceDelete,  s: ToolInputSchemas.workspace_delete,  d: DangerLevel.DANGEROUS, lo: true, p: P.WRITE },
404→      file_delete:       { h: handleFileDelete,       s: ToolInputSchemas.file_delete,       d: DangerLevel.DANGEROUS, lo: true, p: P.WRITE },
405→      folder_delete:     { h: handleFolderDelete,     s: ToolInputSchemas.folder_delete,     d: DangerLevel.DANGEROUS, lo: true, p: P.WRITE },
406→      workspace_sync:    { h: handleWorkspaceSync,    s: ToolInputSchemas.workspace_sync,    d: DangerLevel.MODERATE,  lo: true, p: P.WRITE },
407→      workspace_publish: { h: handleWorkspacePublish, s: ToolInputSchemas.workspace_publish, d: DangerLevel.MODERATE,  lo: true, p: P.WRITE },
408→
409→      // TASK — not local-only (metadata operations)
410→      task_create:  { h: handleTaskCreate,  s: ToolInputSchemas.task_create,  d: DangerLevel.MODERATE, p: P.WRITE },
411→      task_status:  { h: handleTaskStatus,  s: ToolInputSchemas.task_status,  d: DangerLevel.SAFE,     p: P.READ },
412→      task_cancel:  { h: handleTaskCancel,  s: ToolInputSchemas.task_cancel,  d: DangerLevel.MODERATE, p: P.WRITE },
413→      task_respond: { h: handleTaskRespond, s: ToolInputSchemas.task_respond, d: DangerLevel.SAFE,     p: P.WRITE },
414→
415→      // INTERACTION — not local-only
416→      ask_user:        { h: handleAskUser,        s: ToolInputSchemas.ask_user,        d: DangerLevel.SAFE, p: P.READ },
417→      report_progress: { h: handleReportProgress, s: ToolInputSchemas.report_progress, d: DangerLevel.SAFE, p: P.READ },
418→
419→      // GITHUB — remote API, not local-only
420→      github_pr_create:     { h: handleGitHubPRCreate,     s: ToolInputSchemas.github_pr_create,     d: DangerLevel.MODERATE, p: P.WRITE },
421→      github_pr_list:       { h: handleGitHubPRList,       s: ToolInputSchemas.github_pr_list,       d: DangerLevel.SAFE,     p: P.READ },
422→      github_pr_view:       { h: handleGitHubPRView,       s: ToolInputSchemas.github_pr_view,       d: DangerLevel.SAFE,     p: P.READ },
423→      github_issue_create:  { h: handleGitHubIssueCreate,  s: ToolInputSchemas.github_issue_create,  d: DangerLevel.MODERATE, p: P.WRITE },
424→      github_issue_list:    { h: handleGitHubIssueList,    s: ToolInputSchemas.github_issue_list,    d: DangerLevel.SAFE,     p: P.READ },
425→      github_branch_create: { h: handleGitHubBranchCreate, s: ToolInputSchemas.github_branch_create, d: DangerLevel.MODERATE, p: P.WRITE },
426→      github_action_status: { h: handleGitHubActionStatus, s: ToolInputSchemas.github_action_status, d: DangerLevel.SAFE,     p: P.READ },
427→      github_search_repos:  { h: handleGitHubSearchRepos,  s: ToolInputSchemas.github_search_repos,  d: DangerLevel.SAFE,     p: P.READ },
428→
429→      // PM — remote API, not local-only
430→      pm_list:    { h: handlePMList,    s: ToolInputSchemas.pm_list,    d: DangerLevel.SAFE,     p: P.READ },
431→      pm_view:    { h: handlePMView,    s: ToolInputSchemas.pm_view,    d: DangerLevel.SAFE,     p: P.READ },
432→      pm_comment: { h: handlePMComment, s: ToolInputSchemas.pm_comment, d: DangerLevel.MODERATE, p: P.WRITE },
433→      pm_update:  { h: handlePMUpdate,  s: ToolInputSchemas.pm_update,  d: DangerLevel.MODERATE, p: P.WRITE },
434→
435→      // WEB — not local-only
436→      web_fetch:  { h: handleWebFetch,  s: ToolInputSchemas.web_fetch,  d: DangerLevel.SAFE, p: P.READ },
437→      web_search: { h: handleWebSearch, s: ToolInputSchemas.web_search, d: DangerLevel.SAFE, p: P.READ },
438→
439→      // BROWSER — local-only (Playwright runs on host)
440→      browser_open:       { h: handleBrowserOpen,       s: ToolInputSchemas.browser_open,       d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
441→      browser_snapshot:   { h: handleBrowserSnapshot,   s: ToolInputSchemas.browser_snapshot,   d: DangerLevel.SAFE,     lo: true, p: P.READ },
442→      browser_action:     { h: handleBrowserAction,     s: ToolInputSchemas.browser_action,     d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
443→      browser_screenshot: { h: handleBrowserScreenshot, s: ToolInputSchemas.browser_screenshot, d: DangerLevel.SAFE,     lo: true, p: P.READ },
444→
445→      // WORKFLOW / CRON / RUNTIME — local-only (shell/process execution)
446→      workflow_create: { h: handleWorkflowCreate, s: ToolInputSchemas.workflow_create, d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
447→      workflow_list:   { h: handleWorkflowList,   s: ToolInputSchemas.workflow_list,   d: DangerLevel.SAFE,     lo: true, p: P.READ },
448→      workflow_run:    { h: handleWorkflowRun,    s: ToolInputSchemas.workflow_run,    d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
449→      workflow_delete: { h: handleWorkflowDelete, s: ToolInputSchemas.workflow_delete, d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
450→      cron_create:     { h: handleCronCreate,     s: ToolInputSchemas.cron_create,     d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
451→      cron_list:       { h: handleCronList,        s: ToolInputSchemas.cron_list,       d: DangerLevel.SAFE,     lo: true, p: P.READ },
452→      cron_delete:     { h: handleCronDelete,     s: ToolInputSchemas.cron_delete,     d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
453→      cron_run:        { h: handleCronRun,         s: ToolInputSchemas.cron_run,        d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
454→      app_run:         { h: handleAppRun,          s: ToolInputSchemas.app_run,         d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
455→      app_test:        { h: handleAppTest,         s: ToolInputSchemas.app_test,        d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
456→      browser_test:    { h: handleBrowserTest,     s: ToolInputSchemas.browser_test,    d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
457→    };
458→
459→    for (const [name, meta] of Object.entries(builtins)) {
460→      const wTools = workspaceTools as Record<string, { description: string }>;
461→      const tTools = taskTools as Record<string, { description: string }>;
462→      const iTools = interactionTools as Record<string, { description: string }>;
463→      const gTools = githubTools as Record<string, { description: string }>;
464→      const pTools = pmTools as Record<string, { description: string }>;
465→      const webT = webTools as Record<string, { description: string }>;
466→      const brT = browserTools as Record<string, { description: string }>;
467→      const wfT = workflowTools as Record<string, { description: string }>;
468→
469→      const description = (wTools[name] || tTools[name] || iTools[name] || gTools[name] || pTools[name] || webT[name] || brT[name] || wfT[name])?.description || 'No description';
470→      logger.info(`Registering builtin tool: ${name}`, { hasHandler: !!meta.h });
471→
472→      this.register({
473→        name: name as ToolName,
474→        description,
475→        handler: meta.h,
476→        schema: meta.s,
477→        danger: meta.d,
478→        localOnly: meta.lo,
479→        permission: meta.p,
480→      });
481→    }
482→  }
483→}
484→
485→// ============================================================================
486→// Utility Functions
487→// ============================================================================
488→
489→function hasExplicitConfirmation(args: unknown): boolean {
490→  if (!args || typeof args !== 'object') return false;
491→  const record = args as Record<string, unknown>;
492→  return record.confirm === true;
493→}
494→
495→function _mapToOpenAIFunction(tool: OrchestratorTool): Record<string, unknown> {
496→  return {
497→    type: 'function',
498→    function: {
499→      name: tool.name,
500→      description: tool.description,
501→      parameters: zodToJsonSchema(tool.schema),
502→    },
503→  };
504→}
505→
506→function zodToJsonSchema(schema: z.ZodSchema): Record<string, unknown> {
507→  // Zod v4: use .type and .def instead of ._def.typeName
508→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
509→  const s = schema as any;
510→
511→  if (s.type === 'object' && s.def?.shape) {
512→    const shape = s.def.shape;
513→    const properties: Record<string, unknown> = {};
514→    const required: string[] = [];
515→
516→    for (const [key, value] of Object.entries(shape)) {
517→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
518→      const field = value as any;
519→
520→      // Use Zod v4's built-in isOptional() method
521→      const isOptional = typeof field.isOptional === 'function' ? field.isOptional() : false;
522→
523→      // Unwrap wrapper types to get the core type
524→      const innerSchema = unwrapZodType(field);
525→      properties[key] = zodTypeToJsonSchema(innerSchema, field);
526→
527→      if (!isOptional) required.push(key);
528→    }
529→
530→    const result: Record<string, unknown> = { type: 'object', properties };
531→    if (required.length > 0) result.required = required;
532→    return result;
533→  }
534→  return { type: 'object', properties: {} };
535→}
536→
537→/** Unwraps default/optional/nullable wrappers to reach core Zod type. */
538→// eslint-disable-next-line @typescript-eslint/no-explicit-any
539→function unwrapZodType(schema: any): any {
540→  let current = schema;
541→  while (current) {
542→    const type = current.type ?? current.def?.type;
543→    if (type === 'default' || type === 'optional' || type === 'nullable') {
544→      current = current.def?.innerType ?? current._def?.innerType;
545→    } else {
546→      return current;
547→    }
548→  }
549→  return schema;
550→}
551→
552→/** Converts one Zod field schema into JSON-schema-like descriptor. */
553→// eslint-disable-next-line @typescript-eslint/no-explicit-any
554→function zodTypeToJsonSchema(innerSchema: any, outerSchema?: any): Record<string, unknown> {
555→  const base: Record<string, unknown> = {};
556→
557→  // In Zod v4, .description is a direct property, also available via .meta()
558→  const desc = outerSchema?.description ?? innerSchema?.description;
559→  if (desc) base.description = desc;
560→
561→  const type = innerSchema?.type ?? innerSchema?.def?.type;
562→
563→  switch (type) {
564→    case 'string': return { ...base, type: 'string' };
565→    case 'number': return { ...base, type: 'number' };
566→    case 'boolean': return { ...base, type: 'boolean' };
567→    case 'enum': {
568→      // Zod v4: enum entries are in .def.entries as { key: value } or .values as array
569→      const entries = innerSchema.def?.entries;
570→      const values = entries ? Object.values(entries) : (innerSchema.values ?? innerSchema.options);
571→      return values ? { ...base, type: 'string', enum: values } : { ...base, type: 'string' };
572→    }
573→    case 'array': {
574→      const itemSchema = innerSchema.def?.element ?? innerSchema.def?.type;
575→      return { ...base, type: 'array', items: itemSchema ? zodTypeToJsonSchema(unwrapZodType(itemSchema)) : { type: 'string' } };
576→    }
577→    default: return { ...base, type: 'string' };
578→  }
579→}
580→
581→export const getToolRegistry = () => ToolRegistry.getInstance();
582→

