      timers.push(id);
      return id;
    },
    setInterval: (fn: (...args: unknown[]) => void, ms: number) => {
      const id = setInterval(fn, Math.max(ms, 100)); // minimum 100ms interval
      intervals.push(id);
      return id;
    },
    clearTimeout,
    clearInterval,

    // User-provided safe globals
    ...resolved.globals,
  };

